'use strict';
const http=require('node:http'),fs=require('node:fs'),path=require('node:path'),{chromium}=require('playwright'),root=process.cwd();
const server=http.createServer((req,res)=>{const p=decodeURIComponent(new URL(req.url,'http://127.0.0.1').pathname),relative=p==='/'?'/experiments/change-journal-prototype/activity-session-manager-real-resume-diagnostic.html':p,file=path.resolve(root,'.'+relative);if(!file.startsWith(root+path.sep)||!fs.existsSync(file)||!fs.statSync(file).isFile()){res.writeHead(404);res.end('Not found');return;}res.writeHead(200,{'content-type':path.extname(file)==='.html'?'text/html; charset=utf-8':'text/javascript; charset=utf-8'});fs.createReadStream(file).pipe(res);});
(async()=>{let browser;try{await new Promise((resolve,reject)=>{server.once('error',reject);server.listen(4182,'127.0.0.1',resolve);});browser=await chromium.launch({headless:true});const page=await browser.newPage();page.on('pageerror',e=>{throw e;});await page.goto('http://127.0.0.1:4182/',{waitUntil:'load'});await page.waitForFunction(()=>document.querySelector('#summary')?.textContent!=='running');const r=await page.evaluate(()=>window.__activitySessionResumeDiagnostic);if(r.error||r.reproduced!==7||r.total!==7)throw Error('Expected 7 actual resume transaction assertions; got '+JSON.stringify(r));r.results.forEach(x=>console.log('BLOCKER CONFIRMED — '+x.name+' — '+x.detail));console.log('ACTUAL ACTIVITY SESSION MANAGER WORDPUZZLE TRANSACTION: PASS (7/7 assertions)');}finally{if(browser)await browser.close();await new Promise(resolve=>server.close(resolve));}})().catch(e=>{console.error(e);process.exitCode=1;});